"use strict";(globalThis.webpackChunkgrc||=[]).push([[75909],{46336(e){e.exports=JSON.parse('[{"citeKey":"tang2025ioworkflows","slug":"tang-2025-ioworkflows-a9f3","title":"Analyzing I/O Patterns and Dataflow in HPC Workflows","authors":["M. Tang","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The 37h International Conference on Scalable Scientific Data Management (SSDBM 2025)","type":"Technical Report","entryType":"misc","date":"June, 2025","year":2025,"era":"iit","month":6,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2025/tang-2025-ioworkflows-a9f3-poster.pdf"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2024dayu","slug":"tang-2024-dayu-f286","title":"DaYu: Optimizing Distributed Scientific Workflows by Decoding Dataflow Semantics and Dynamics","authors":["M. Tang","J. Cernuda","J. Ye","L. Guo","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"2024 IEEE International Conference on Cluster Computing (CLUSTER\'24)","type":"Conference","entryType":"inproceedings","date":"September, 2024","year":2024,"era":"iit","month":9,"doi":"10.1109/cluster59578.2024.00038","abstract":"The combination of ever-growing scientific datasets and distributed workflow complexity creates I/O performance bottlenecks due to data volume, velocity, and variety. Although the increasing use of descriptive data formats (e.g., HDF5, netCDF) helps organize these datasets, it also introduces obscure bottlenecks due to the need to translate high-level operations into file addresses and then into low-level I/O operations. To address this challenge, we introduce DaYu, a method and toolset for analyzing (a) semantic relationships between logical datasets and file addresses, (b) how dataset operations translate into I/O, and (c) the combination across entire workflows. DaYu\'s analysis and visualization enable the identification of critical bottlenecks and the reasoning about remediation. We describe our methodology and propose optimization guidelines. Evaluation on scientific workflows demonstrates up to a 3.7x performance improvement in I/O time for obscure bottlenecks. The time and storage overhead for DaYu\'s time-ordered data are typically under 0.2% of runtime and 0.25% of data volume, respectively.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/tang-2024-dayu-f286.pdf"},"tags":["Data Analytics","Modeling","Performance Measurement","Tools","Workflow Optimization"],"_projectIds":["portus"],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"lee2023datalifecycles","slug":"lee-2023-data-lifecycles-c393","title":"Data Flow Lifecycles for Optimizing Workflow Coordination","authors":["H. Lee","L. Guo","M. Tang","J. Firoz","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Conference","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3581784.3607104","abstract":"A critical performance challenge in distributed scientific workflows is coordinating tasks and data flows on distributed resources. To guide these decisions, this paper introduces data flow lifecycle anal- ysis. Workflows are commonly represented using directed acyclic graphs (DAGs). Data flow lifecycles (DFL) enrich task DAGs with data objects and properties that describe data flow and how tasks interact with that flow. Lifecycles enable analysis from several important perspectives: task, data, and data flow. We describe rep- resentation, measurement, analysis, visualization, and opportunity identification for DFLs. Our measurement is both distributed and scalable, using space that is constant per data file. We use lifecycles and opportunity analysis to reason about improved task placement and reduced data movement for five scientific workflows with dif- ferent characteristics. Case studies show improvements of 15x, 1.9\xd7, and 10-30x. Our work is implemented in the DataLife tool.","hasAbstract":true,"lede":"To guide these decisions, this paper introduces data flow lifecycle anal- ysis.","pages":"1\u201315","links":{"pdf":"https://grc.iit.edu/papers/2023/lee-2023-data-lifecycles-c393.pdf"},"tags":["Data Analytics","Performance Measurement","Modeling","Tools"],"_projectIds":[],"_funding":[{"agency":"PNNL","award":"DE-AC05-76RL01830","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"tang2023semanticworkflow","slug":"tang-2023-semantic-workflow-e12d","title":"Optimizing Workflow Performance by Elucidating Semantic Data Flow","authors":["M. Tang","N. Tallent","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'23)","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/tang-2023-semantic-workflow-e12d-poster.pdf"},"tags":["HPC Analysis","I/O","Workflow Optimization","Data Analytics","Performance Measurement"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);